async function createFromParts(multihash: Uint8Array, privKey?: Uint8Array, pubKey?: Uint8Array): Promise<PeerId> {
  if (privKey != null) {
    const key = await unmarshalPrivateKey(privKey);

    return createFromPrivKey(key);
